  function toCN(text) {
    return Array.from(String(text || "")).map(function (ch) { return CN[ch] || ch; }).join("");
  }

  const NC = {};
  Object.keys(CN).forEach(function (tw) {
    const cn = CN[tw];
    if (cn && cn !== tw && !NC[cn]) NC[cn] = tw;
  });
  // 台文常用字本身不要被反向表改成冷僻異體（例如 台→檯）
  ["台", "里", "面", "松", "云", "后", "谷", "升", "余", "冲", "卤", "奸", "尸", "岳", "范", "庄", "万", "与", "丰"].forEach(function (ch) {
    delete NC[ch];
  });
  NC["台"] = "台";
  NC["裡"] = "裡";
  NC["臺"] = "臺";

  function toTW(text) {
    return Array.from(String(text || "")).map(function (ch) { return NC[ch] || ch; }).join("");
  }

  function hasCjk(text) {
    return /[\u4e00-\u9fff]/.test(String(text || ""));
  }

  let codeNameMap = null;
  function codeTwName(code) {
    if (!codeNameMap) {
      codeNameMap = {};
      UNIVERSE.forEach(function (row) {
        if (row.code && row.name) codeNameMap[String(row.code).toUpperCase()] = row.name;
      });
      // INV_ALIASES 在下方宣告；首次呼叫時通常已就緒
      if (typeof INV_ALIASES !== "undefined") {
        INV_ALIASES.forEach(function (row) {
          if (row.code && row.name) codeNameMap[String(row.code).toUpperCase()] = row.name;
        });
      }
      codeNameMap["3189"] = codeNameMap["3189"] || "景碩";
      codeNameMap["2345"] = codeNameMap["2345"] || "智邦";
    }
    return codeNameMap[String(code || "").toUpperCase()] || "";
  }

  function preferTwName(current, incoming, code) {
    const cur = toTW(current || "");
    const inc = toTW(incoming || "");
    const known = codeTwName(code);
    if (hasCjk(cur)) return cur;
    if (hasCjk(inc)) return inc;
    if (known) return known;
    return cur || inc || String(code || "");
  }

  function indexRegion(code) {
    const map = { DJIA: "美股", SPX: "美股", NDX: "美股", SOX: "美股", TWII: "台股", N225: "日股", KS11: "韓股" };
    return map[code] || "指數";
  }

  const FX_QUERY = {
    "1d": "interval=1m&range=1d",
    "5d": "interval=15m&range=5d",
    "20d": "interval=1d&range=1mo",
    "180d": "interval=1d&range=1y",
    "1y": "interval=1d&range=1y",
    "3y": "interval=1wk&range=5y",
    "5y": "interval=1wk&range=5y"
  };
  const FX_KEEP = { "20d": 20, "180d": 180, "1y": 250, "3y": 160 };

  function isoDaysAgo(days) {
    const d = new Date();
    d.setDate(d.getDate() - days);
    const m = String(d.getMonth() + 1).padStart(2, "0");
    const day = String(d.getDate()).padStart(2, "0");
    return d.getFullYear() + "-" + m + "-" + day;
  }

  function taipeiStamp(epochSec) {
    const x = new Date(epochSec * 1000 + 8 * 3600 * 1000);
    const p = function (n) { return String(n).padStart(2, "0"); };
    return x.getUTCFullYear() + "-" + p(x.getUTCMonth() + 1) + "-" + p(x.getUTCDate()) + " " + p(x.getUTCHours()) + ":" + p(x.getUTCMinutes());
  }

  function barsFromYahoo(json) {
    const chart = json && json.chart;
    if (!chart || !chart.result || !chart.result.length) throw new Error("沒有匯率");
    const row = chart.result[0];
    const ts = row.timestamp || [];
    const q = (row.indicators && row.indicators.quote && row.indicators.quote[0]) || {};
    const bars = [];
    for (let i = 0; i < ts.length; i++) {
      const c = num(q.close && q.close[i]);
      if (!(c > 0)) continue;
      bars.push({
        t: taipeiStamp(ts[i]),
        o: num(q.open && q.open[i]) || c,
        c: c,
        h: num(q.high && q.high[i]) || c,
        l: num(q.low && q.low[i]) || c,
        v: num(q.volume && q.volume[i]) || 0
      });
    }
    if (!bars.length) throw new Error("沒有匯率");
    return bars;
  }

  function fxQueryForWindow(from, to) {
    const days = spanDays(from, to);
    if (days <= 1) return "interval=1m&range=1d";
    if (days <= 5) return "interval=15m&range=5d";
    if (days <= 40) return "interval=1d&range=1mo";
    if (days <= 400) return "interval=1d&range=2y";
    return "interval=1wk&range=5y";
  }

  async function fxBars(rangeId, window) {
    const from = window && window.from;
    const to = window && window.to;
    const query = from && to ? fxQueryForWindow(from, to) : (FX_QUERY[rangeId] || FX_QUERY["20d"]);
    const key = "fx|" + query;
    let rows = cache.get(key);
    if (!rows) {
      rows = barsFromYahoo(await yahooChart("TWD=X", query));
      rows.symbolName = "台幣對美金";
      cache.set(key, rows);
    }
    if (from && to) {
      const cut = clipBars(rows, from, to);
      if (!cut.length) throw new Error("這段日期沒有匯率");
      return cut;
    }
    const keep = FX_KEEP[rangeId];
    const out = keep ? rows.slice(-keep) : rows.slice();
    out.symbolName = "台幣對美金";
    return copyBars(out);
  }

  async function foreignNets() {
    const key = "foreign|nets";
    if (cache.has(key)) return cache.get(key);
    const url = "https://api.finmindtrade.com/api/v4/data?dataset=TaiwanStockTotalInstitutionalInvestors&start_date=" + isoDaysAgo(460);
    const res = await fetch(url);
    if (!res.ok) throw new Error("外資買賣超讀取失敗");
    const json = await res.json();
    const nets = (json.data || []).filter(function (row) {
      return row.name === "Foreign_Investor";
    }).map(function (row) {
      return { date: row.date, net: (num(row.buy) - num(row.sell)) / 1e8 };
    }).filter(function (row) { return isFinite(row.net); });
    nets.sort(function (a, b) { return a.date < b.date ? -1 : a.date > b.date ? 1 : 0; });
    function sumLast(n) {
      const slice = nets.slice(-n);
      if (!slice.length) return null;
      return slice.reduce(function (acc, row) { return acc + row.net; }, 0);
    }
    const out = { "1d": sumLast(1), "5d": sumLast(5), "20d": sumLast(20), "180d": sumLast(180), "1y": sumLast(250) };
    cache.set(key, out);
    return out;
  }

  let yahooDirect = true;

  function yahooCandidates(secid) {
    const id = String(secid || "");
    const known = {
      "100.DJIA": ["^DJI"],
      "100.SPX": ["^GSPC"],
      "100.NDX": ["^NDX"],
      "100.TWII": ["^TWII"],
      "100.N225": ["^N225"],
      "100.KS11": ["^KS11"],
      "251.SOX": ["^SOX"],
      "fx.USDTWD": ["TWD=X"]
    };
    if (known[id]) return known[id];
    const dot = id.indexOf(".");
    if (dot < 0) return [];
    const prefix = id.slice(0, dot);
    const code = id.slice(dot + 1).toUpperCase();
    if (prefix === "178" || prefix === "tw") return [code + ".TW", code + ".TWO"];
    if (prefix === "105" || prefix === "106") return [code];
    if (prefix === "176") return [code + ".T"];
    if (prefix === "177") return [code + ".KS"];
    return [];
  }

  async function yahooChart(symbol, query) {
    const path = "https://query1.finance.yahoo.com/v8/finance/chart/" + encodeURIComponent(symbol) + "?" + (query || "interval=1d&range=1d");
    if (yahooDirect) {
      try {
        const res = await fetch(path);
        if (res.ok) return await res.json();
        yahooDirect = false;
      } catch (err) {
        yahooDirect = false;
      }
    }
    const relay = await fetch("https://r.jina.ai/" + path);
    if (!relay.ok) throw new Error("Yahoo 報價讀取失敗");
    const text = await relay.text();
    const start = text.indexOf("{");
    const end = text.lastIndexOf("}");
    if (start < 0 || end <= start) throw new Error("Yahoo 沒有回傳成交價");
    return JSON.parse(text.slice(start, end + 1));
  }

  async function yahooQuote(secid) {
    const symbols = yahooCandidates(secid);
    // 先 1 分 K 取盤中最新成交；日線備援。避免代理快取把「昨收」當成現價。
    const queries = ["interval=1m&range=1d", "interval=1d&range=5d"];
    for (let i = 0; i < symbols.length; i++) {
      for (let q = 0; q < queries.length; q++) {
        try {
          const json = await yahooChart(symbols[i], queries[q]);
          const chart = json && json.chart;
          if (!chart || (chart.error && chart.error !== null) || !chart.result || !chart.result.length) continue;
          const result = chart.result[0] || {};
          const meta = result.meta || {};
          const closes = ((((result.indicators || {}).quote || [])[0] || {}).close || [])
            .filter(function (v) { return v != null && isFinite(Number(v)) && Number(v) > 0; })
            .map(Number);
          const lastBar = closes.length ? closes[closes.length - 1] : null;
          const metaPx = num(meta.regularMarketPrice) || num(meta.postMarketPrice);
          // 1 分 K 最後一筆通常比 meta／代理快取新
          let price = q === 0 && lastBar > 0 ? lastBar : (metaPx || lastBar);
          if (!(price > 0)) continue;
          const prev = num(meta.previousClose) || num(meta.chartPreviousClose);
          const metaPct = num(meta.regularMarketChangePercent);
          let change = prev ? price - prev : num(meta.regularMarketChange);
          let pct = prev ? (price - prev) / prev * 100 : metaPct;
          // previousClose 過舊時改信 Yahoo 百分比／近兩根日線
          if (metaPct != null && isFinite(metaPct) && prev > 0) {
            const impliedPrev = price / (1 + metaPct / 100);
            if (Math.abs(prev - impliedPrev) / price > 0.02) {
              if (closes.length >= 2 && q === 1) {
                const dayPrev = closes[closes.length - 2];
                change = price - dayPrev;
                pct = change / dayPrev * 100;
              } else {
                pct = metaPct;
                change = price - impliedPrev;
              }
            }
          }
          const code = String(secid).slice(String(secid).indexOf(".") + 1).toUpperCase();
          return {
            secid: secid,
            code: code,
            name: toTW(meta.shortName || meta.symbol || code),
            price: price,
            change: change,
            pct: pct,
            pe: null,
            cap: null,
            pb: null,
            source: "yahoo"
          };
        } catch (err) { /* 下一個查詢／代號 */ }
      }
    }
    return null;
  }

  const quoteFresh = new Map();

  async function quoteMap(secids) {
    const ids = (secids || []).filter(Boolean);
    const out = {};
    if (!ids.length) return out;
    const missed = [];
    const need = [];
    const now = Date.now();
    ids.forEach(function (id) {
      const hit = quoteFresh.get(id);
      if (hit && now - hit.at < 60000) out[id] = hit.quote;
      else need.push(id);
    });
    await mapPool(need, 4, async function (id) {
      const quote = await yahooQuote(id);
      if (quote) {
        out[id] = quote;
        quoteFresh.set(id, { at: Date.now(), quote: quote });
      } else missed.push(id);
    });
    if (missed.length) {
      const rest = await quoteFeed(missed);
      Object.keys(rest).forEach(function (id) {
        out[id] = rest[id];
        quoteFresh.set(id, { at: Date.now(), quote: rest[id] });
      });
    }
    return out;
  }

  async function quoteFeed(secids) {
    const ids = (secids || []).filter(Boolean);
    const out = {};
    if (!ids.length) return out;
    const em = ids.filter(function (id) { return id.indexOf("tw.") !== 0; });
    const tw = ids.filter(function (id) { return id.indexOf("tw.") === 0; });
    if (em.length) {
      const url = "https://push2delay.eastmoney.com/api/qt/ulist.np/get?fltt=2&secids=" +
        encodeURIComponent(em.join(",")) + "&fields=f12,f13,f14,f2,f3,f9,f20,f23";
      const res = await fetch(url);
      if (!res.ok) throw new Error("報價讀取失敗");
      const json = await res.json();
      const rows = (json.data && json.data.diff) || [];
      rows.forEach(function (row) {
        const secid = row.f13 + "." + row.f12;
        out[secid] = {
          secid: secid,
          code: row.f12,
          name: toTW(row.f14),
          price: num(row.f2),
          pct: num(row.f3),
          pe: num(row.f9),
          cap: num(row.f20),
          pb: num(row.f23)
        };
      });
    }
    if (tw.length) {
      const board = await cnyesQuotes(tw.map(function (id) { return id.slice(3); }));
      Object.keys(board).forEach(function (code) {
        const row = board[code];
        out[row.secid] = row;
      });
    }
    return out;
  }

  function parseCnyesQuote(row) {
    const code = String(row["200010"] || "").toUpperCase();
    if (!code) return null;
    const price = num(row["6"]);
    const change = num(row["11"]);
    const high = num(row["12"]);
    const low = num(row["13"]);
    const open = num(row["19"]);
    const ref = num(row["21"]);
    const pct = num(row["56"]);
    const limitUp = num(row["75"]);
    const limitDown = num(row["76"]);
    const volumeLots = num(row["200013"]);
    const amount = num(row["200067"]);
    const avg = (amount > 0 && volumeLots > 0) ? amount / (volumeLots * 1000) : null;
    const amplitude = (high != null && low != null && ref > 0) ? (high - low) / ref * 100 : null;
    return {
      secid: "tw." + code,
      code: code,
      name: toTW(row["200009"] || code),
      price: price,
      change: change,
      pct: pct,
      open: open,
      high: high,
      low: low,
      ref: ref,
      limitUp: limitUp,
      limitDown: limitDown,
      volumeLots: volumeLots,
      amount: amount,
      avg: avg,
      amplitude: amplitude,
      pe: null,
      cap: null,
      pb: null
    };
  }

  async function cnyesQuotes(codes) {
    const ids = (codes || []).map(function (c) { return String(c || "").toUpperCase(); }).filter(Boolean);
    const out = {};
    if (!ids.length) return out;
    const uniq = [];
    ids.forEach(function (c) { if (uniq.indexOf(c) < 0) uniq.push(c); });
    const chunks = [];
    for (let i = 0; i < uniq.length; i += 8) chunks.push(uniq.slice(i, i + 8));
    await mapPool(chunks, 2, async function (part) {
      const q = part.map(function (c) { return "TWS:" + c + ":STOCK"; }).join(",");
      const res = await fetch("https://ws.api.cnyes.com/ws/api/v1/quote/quotes/" + q);
      if (!res.ok) throw new Error("台股報價讀取失敗");
      const json = await res.json();
      const rows = Array.isArray(json.data) ? json.data : [];
      rows.forEach(function (row) {
        const parsed = parseCnyesQuote(row);
        if (parsed) out[parsed.code] = parsed;
      });
    });
    return out;
  }

  function sma(values, n) {
    const out = new Array(values.length).fill(null);
    let sum = 0;
    for (let i = 0; i < values.length; i++) {
      sum += values[i];
      if (i >= n) sum -= values[i - n];
      if (i >= n - 1) out[i] = sum / n;
    }
    return out;
  }

  function ema(values, n) {
    const out = new Array(values.length).fill(null);
    const k = 2 / (n + 1);
    let prev = null;
    let sum = 0;
    for (let i = 0; i < values.length; i++) {
      sum += values[i];
      if (i === n - 1) {
        prev = sum / n;
        out[i] = prev;
      } else if (i >= n) {
        prev = values[i] * k + prev * (1 - k);
        out[i] = prev;
      }
    }
    return out;
  }

  function rsi(values, n) {
    const out = new Array(values.length).fill(null);
    if (values.length <= n) return out;
    let gain = 0;
    let loss = 0;
    for (let i = 1; i <= n; i++) {
      const d = values[i] - values[i - 1];
      if (d >= 0) gain += d;
      else loss -= d;
    }
    gain /= n;
    loss /= n;
    out[n] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
    for (let i = n + 1; i < values.length; i++) {
      const d = values[i] - values[i - 1];
      const g = d > 0 ? d : 0;
      const l = d < 0 ? -d : 0;
      gain = (gain * (n - 1) + g) / n;
      loss = (loss * (n - 1) + l) / n;
      out[i] = loss === 0 ? 100 : 100 - 100 / (1 + gain / loss);
    }
    return out;
  }

  function macd(values) {
    const e12 = ema(values, 12);
    const e26 = ema(values, 26);
    const line = values.map(function (_, i) {
      return e12[i] == null || e26[i] == null ? null : e12[i] - e26[i];
    });
    const compact = [];
    const index = [];
    line.forEach(function (v, i) {
      if (v != null) {
        compact.push(v);
        index.push(i);
      }
    });
    const signalCompact = ema(compact, 9);
    const signal = new Array(values.length).fill(null);
    const hist = new Array(values.length).fill(null);
    signalCompact.forEach(function (v, j) {
      if (v == null) return;
      const i = index[j];
      signal[i] = v;
      hist[i] = line[i] - v;
    });
    return { line: line, signal: signal, hist: hist };
  }

  function atr(bars, n) {
    const tr = bars.map(function (b, i) {
      if (i === 0) return (b.h != null && b.l != null) ? b.h - b.l : 0;
      const prev = bars[i - 1].c;
      return Math.max(b.h - b.l, Math.abs(b.h - prev), Math.abs(b.l - prev));
    });
    return sma(tr, n);
  }

  function closesOf(bars) {
    return bars.map(function (b) { return b.c; });
  }

  function lastValid(arr) {
    for (let i = arr.length - 1; i >= 0; i--) if (arr[i] != null) return arr[i];
    return null;
  }

  function swings(bars, span) {
    const highs = [];
    const lows = [];
    for (let i = span; i < bars.length - span; i++) {
      let isH = true;
      let isL = true;
      for (let j = i - span; j <= i + span; j++) {
        if (bars[j].h > bars[i].h) isH = false;
        if (bars[j].l < bars[i].l) isL = false;
      }
      if (isH) highs.push(bars[i].h);
      if (isL) lows.push(bars[i].l);
    }
    return { highs: highs, lows: lows };
  }

  function slopeText(values) {
    const n = values.length;
    if (n < 10) return "樣本太短，看不出趨勢線。";
    let sx = 0, sy = 0, sxx = 0, sxy = 0;
    for (let i = 0; i < n; i++) {
      sx += i; sy += values[i]; sxx += i * i; sxy += i * values[i];
    }
    const den = n * sxx - sx * sx;
    const slope = den ? (n * sxy - sx * sy) / den : 0;
    const pct = values[0] ? (slope / values[0]) * 100 : 0;
    if (pct > 0.08) return "近 " + n + " 根收盤的回歸線向上，每根約 " + pct.toFixed(2) + "%。";
    if (pct < -0.08) return "近 " + n + " 根收盤的回歸線向下，每根約 " + pct.toFixed(2) + "%。";
    return "近 " + n + " 根收盤的回歸線接近走平，每根約 " + pct.toFixed(2) + "%。";
  }

  function roundPx(n) {
    if (!isFinite(n)) return null;
    if (Math.abs(n) >= 1000) return Math.round(n * 100) / 100;
    if (Math.abs(n) >= 100) return Math.round(n * 100) / 100;
    return Math.round(n * 1000) / 1000;
  }

  function capText(cap) {
    if (!isFinite(cap) || cap <= 0) return "";
    if (cap >= 1e12) return "市值約 " + (cap / 1e12).toFixed(2) + " 兆";
    if (cap >= 1e8) return "市值約 " + (cap / 1e8).toFixed(0) + " 億";
    return "市值約 " + Math.round(cap).toLocaleString("zh-Hant");
  }

  function fundLine(q) {
    if (!q) return "報價站沒有本益比或市值，這次只看技術面。";
    const bits = [];
    if (isFinite(q.pe) && q.pe > 0) {
      let tone = "本益比 " + q.pe.toFixed(1);
      if (q.pe < 12) tone += "，獲利收益率偏高";
      else if (q.pe > 40) tone += "，評價偏貴，部位應以技術結構為主";
      else tone += "，評價落在常見區間";
      bits.push(tone);
    } else bits.push("沒有可用本益比");
    if (isFinite(q.pb) && q.pb > 0) bits.push("股價淨值 " + q.pb.toFixed(2));
    const cap = capText(q.cap);
    if (cap) bits.push(cap);
    return bits.join("，") + "。";
  }

  function scoreOne(meta, bars) {
    const c = closesOf(bars);
    const i = c.length - 1;
    if (i < 60) return null;
    const s20 = sma(c, 20);
    const s60 = sma(c, 60);
    const s120 = sma(c, Math.min(120, c.length));
    const rv = rsi(c, 14);
    const md = macd(c);
    const at = atr(bars, 14);
    const close = c[i];
    const rsiNow = rv[i];
    const atrNow = at[i] || close * 0.02;
    let hh = -Infinity;
    let volSum = 0;
    let volN = 0;
    for (let k = i - 20; k < i; k++) {
      if (k < 0) continue;
      hh = Math.max(hh, bars[k].h);
      volSum += bars[k].v || 0;
      volN++;
    }
    const avgVol = volN ? volSum / volN : 0;
    const vol = bars[i].v || 0;
    let swing = close;
    for (let k = Math.max(0, i - 7); k <= i; k++) swing = Math.min(swing, bars[k].l);
    let stop = Math.min(swing, close - 1.5 * atrNow);
    if (!(stop < close * 0.995)) stop = close - 1.5 * atrNow;
    if (!(stop < close)) stop = close * 0.97;
    const risk = close - stop;
    const target = close + 2 * risk;
    const dist = s20[i] ? Math.abs(close - s20[i]) / s20[i] : 1;
    let score = 48;
    const upTrend = s20[i] != null && s60[i] != null && close > s60[i] && s20[i] > s60[i];
    const breakout = isFinite(hh) && close > hh && close > (s60[i] || 0) && avgVol > 0 && vol > avgVol * 1.35;
    const pullback = upTrend && dist < 0.025 && rsiNow >= 38 && rsiNow <= 62;
    const bounce = rsiNow != null && rsiNow < 35 && s120[i] != null && close > s120[i] && md.hist[i] != null && md.hist[i - 1] != null && md.hist[i] > md.hist[i - 1];
    if (close > (s60[i] || close)) score += 8; else score -= 12;
    if (s20[i] != null && s60[i] != null && s20[i] > s60[i]) score += 8; else score -= 8;
    if (rsiNow >= 40 && rsiNow <= 62) score += 8;
    if (rsiNow != null && rsiNow < 30) score -= 4;
    if (breakout) score += 14;
    if (pullback) score += 12;
    if (bounce) score += 6;
    let setup = "沒有明確結構";
    if (breakout) setup = "區間突破";
    else if (pullback) setup = "均線回檔";
    else if (bounce) setup = "超賣反彈";
    const tradable = score >= 68 && (breakout || pullback);
    const reasons = [];
    reasons.push(upTrend ? "日線收在 60 日均線上，20 日均線也在 60 日之上，趨勢仍偏多。" : "日線還沒有 20 日與 60 日均線同時向上的多頭排列。");
    if (breakout) reasons.push("收盤突破前 20 根高點，量能高於 20 日均量，屬於突破結構。");
    else if (pullback) reasons.push("價格回到 20 日均線附近（距離 " + (dist * 100).toFixed(1) + "%），RSI " + rsiNow.toFixed(0) + "，是順勢回檔而不是追高。");
    else if (bounce) reasons.push("RSI " + rsiNow.toFixed(0) + " 進入超賣，MACD 柱狀轉強，但仍要等站回短均線。");
    else reasons.push("RSI " + (rsiNow == null ? "—" : rsiNow.toFixed(0)) + "，與 20 日均線距離 " + (dist * 100).toFixed(1) + "%，沒有同時滿足突破或回檔。");
    reasons.push("停損放在近 8 根低點與 1.5 倍 ATR 的較低者，停利先以 2 倍風險計算。");
    return {
      secid: meta.secid,
      code: meta.code,
      name: meta.name,
      market: meta.market,
      badge: tradable ? "可進場" : "僅觀察",
      setup: setup,
      score: score,
      entry: roundPx(close),
      stop: roundPx(stop),
      target: roundPx(target),
      rr: risk > 0 ? 2 : null,
      atr: atrNow,
      reasons: reasons
    };
  }

  async function scan(opts) {
    opts = opts || {};
    const capital = Number(opts.capital) > 0 ? Number(opts.capital) : 1000000;
    const riskPct = Number(opts.riskPct) > 0 ? Number(opts.riskPct) : 1;
    const market = opts.market || "台股";
    const limit = Math.max(1, Math.min(20, Math.floor(Number(opts.limit) || 5)));
    const pool = UNIVERSE.filter(function (meta) {
      return !market || market === "全部" || meta.market === market;
    });
    let done = 0;
    const rows = await mapPool(pool, 3, async function (meta) {
      try {
        const raw = await kline(meta.secid, 101, 180);
        const idea = scoreOne(meta, raw);
        done++;
        if (opts.onProgress) opts.onProgress(done, pool.length, meta.name);
        return idea;
      } catch (err) {
        done++;
        if (opts.onProgress) opts.onProgress(done, pool.length, meta.name);
        return null;
      }
    });
    const ideas = rows.filter(Boolean).sort(function (a, b) { return b.score - a.score; }).slice(0, limit);
    let quotes = {};
    try { quotes = await quoteMap(ideas.map(function (item) { return item.secid; })); } catch (e) { quotes = {}; }
    ideas.forEach(function (item, idx) {
      item.rank = idx + 1;
      const risk = item.entry - item.stop;
      item.shares = risk > 0 ? Math.floor(capital * (riskPct / 100) / risk) : 0;
      item.fundamental = fundLine(quotes[item.secid]);
      item.riskCash = capital * (riskPct / 100);
    });
    return {
      scanned: pool.length,
      kept: ideas.length,
      tradable: ideas.filter(function (item) { return item.badge === "可進場"; }).length,
      ideas: ideas
    };
  }

  async function technical(secid) {
    const daily = await kline(secid, 101, 260);
    const weekly = await kline(secid, 102, 80);
    const name = daily.symbolName || secid;
    const c = closesOf(daily);
    const i = c.length - 1;
    const close = c[i];
    const s5 = sma(c, 5);
    const s20 = sma(c, 20);
    const s60 = sma(c, 60);
    const s120 = sma(c, 120);
    const rv = rsi(c, 14);
    const md = macd(c);
    const sw = swings(daily, 3);
    const wc = closesOf(weekly);
    const w20 = sma(wc, 20);
    const wClose = wc[wc.length - 1];
    const wMa = lastValid(w20);
    const weeklyUp = wMa != null && wClose > wMa;
    const maUp = s20[i] != null && s60[i] != null && close > s20[i] && s20[i] > s60[i];
    const macdUp = md.hist[i] != null && md.hist[i] > 0;
    const rsiOk = rv[i] != null && rv[i] >= 45 && rv[i] <= 70;
    const rsiWeak = rv[i] != null && rv[i] < 45;
    const maDown = s20[i] != null && s60[i] != null && close < s20[i] && s20[i] < s60[i];
    const macdDown = md.hist[i] != null && md.hist[i] < 0;
    let verdict = "觀望";
    if (maUp && macdUp && rsiOk && weeklyUp) verdict = "買進";
    else if (maDown && macdDown && rsiWeak && !weeklyUp) verdict = "賣出";
    const steps = [
      { name: "週線方向", pass: weeklyUp, detail: weeklyUp ? "週線收在 20 週均線上。" : "週線還沒站上 20 週均線。" },
      { name: "日線均線", pass: maUp, detail: maUp ? "收盤 > 20 日 > 60 日。" : "日線沒有多頭排列。" },
      { name: "MACD", pass: macdUp, detail: macdUp ? "MACD 柱狀在零軸上。" : "MACD 柱狀還在零軸下或剛走平。" },
      { name: "RSI", pass: rsiOk, detail: "RSI(14) 為 " + (rv[i] == null ? "—" : rv[i].toFixed(1)) + "。買進區看 45 到 70。" }
    ];
    if (verdict === "賣出") {
      steps.push({ name: "空頭確認", pass: true, detail: "均線空頭、MACD 為負、RSI 低於 45，週線也沒有轉強。" });
    }
    const supports = sw.lows.filter(function (p) { return p < close; }).slice(-3);
    const resistances = sw.highs.filter(function (p) { return p > close; }).slice(-3);
    const mas = [
      { name: "5 日", value: s5[i], above: s5[i] != null && close >= s5[i] },
      { name: "20 日", value: s20[i], above: s20[i] != null && close >= s20[i] },
      { name: "60 日", value: s60[i], above: s60[i] != null && close >= s60[i] },
      { name: "120 日", value: s120[i], above: s120[i] != null && close >= s120[i] }
    ];
    const histNow = md.hist[i];
    const histPrev = md.hist[i - 1];
    let momentum = "RSI " + (rv[i] == null ? "—" : rv[i].toFixed(1)) + "。";
    if (histNow != null) {
      momentum += " MACD 柱 " + histNow.toFixed(2);
      if (histPrev != null) momentum += histNow > histPrev ? "，柱狀放大。" : "，柱狀縮小。";
      else momentum += "。";
    }
    return {
      secid: secid,
      name: name,
      close: roundPx(close),
      verdict: verdict,
      steps: steps,
      supports: supports.map(roundPx),
      resistances: resistances.map(roundPx),
      trend: slopeText(c.slice(-60)),
      mas: mas.map(function (m) { return { name: m.name, value: roundPx(m.value), above: m.above }; }),
      momentum: momentum,
      weekly: weeklyUp ? "週線偏多，日線信號可以順著做。" : "週線尚未轉多，日線反彈先當反彈看。"
    };
  }

  function splitNews(text) {
    return String(text || "").split(/[\n。！？!?；;]+/).map(function (s) { return s.trim(); }).filter(Boolean).slice(0, 8);
  }

  async function newsPlan(opts) {
    opts = opts || {};
    const daily = await kline(opts.secid, 101, 180);
    const c = closesOf(daily);
    const i = c.length - 1;
    const close = c[i];
    const at = atr(daily, 14);
    const atrNow = at[i] || close * 0.02;
    const back5 = c[Math.max(0, i - 5)];
    const back20 = c[Math.max(0, i - 20)];
    const ret5 = back5 ? close / back5 - 1 : 0;
    const ret20 = back20 ? close / back20 - 1 : 0;
    const atrPct = close ? atrNow / close : 0;
    const priced = Math.abs(ret5) > atrPct * 2;
    const sentences = splitNews(opts.text);
    const seen = [];
    const unseen = [];
    sentences.forEach(function (line) {
      if (/將|預計|下季|明年|計畫|計劃|預期|將於/.test(line)) unseen.push(line);
      else if (/已|公布|公告|昨日|今天|本日|上季|去年/.test(line)) seen.push(line);
    });
    const posWords = (opts.text || "").match(/成長|上修|優於|買回|增產|利多|超預期|beat|raise|訂單/ig) || [];
    const negWords = (opts.text || "").match(/下修|衰退|調查|裁員|不如|利空|虧損|miss|延遲|禁令/ig) || [];
    let bias = "中性";
    if (posWords.length > negWords.length) bias = "偏多";
    else if (negWords.length > posWords.length) bias = "偏空";
    const capital = Number(opts.capital) > 0 ? Number(opts.capital) : 1000000;
    const riskPct = Number(opts.riskPct) > 0 ? Number(opts.riskPct) : 1;
    const stop = close - 1.5 * atrNow;
    const shares = stop < close ? Math.floor(capital * (riskPct / 100) / (close - stop)) : 0;
    let quotes = {};
    try { quotes = await quoteMap([opts.secid]); } catch (e) { quotes = {}; }
    return {
      name: daily.symbolName || opts.secid,
      close: roundPx(close),
      bias: bias,
      shortRange: [roundPx(close - 1.2 * atrNow), roundPx(close + 1.2 * atrNow)],
      longRange: [roundPx(close - 3 * atrNow), roundPx(close + 3 * atrNow)],
      ret5: ret5,
      ret20: ret20,
      priced: priced,
      pricedText: priced
        ? "近 5 日漲跌 " + (ret5 * 100).toFixed(1) + "%，已超過兩倍單日 ATR，短線消息有一部分可能已經反映在價格裡。"
        : "近 5 日漲跌 " + (ret5 * 100).toFixed(1) + "%，還在約一個 ATR 的平常波動裡，價格還沒有明顯消化這則消息。",
      seen: seen,
      unseen: unseen,
      noTime: !seen.length && !unseen.length,
      shares: shares,
      stop: roundPx(stop),
      riskCash: capital * (riskPct / 100),
      fundamental: fundLine(quotes[opts.secid]),
      weeklyNote: "20 日漲跌 " + (ret20 * 100).toFixed(1) + "%。長期區間用 3 倍 ATR，約一個月的平常擺動，不是目標價。"
    };
  }

  function tradeMetrics(bars, kind) {
    const c = closesOf(bars);
    const s5 = sma(c, 5);
    const s20 = sma(c, 20);
    const s60 = sma(c, 60);
    const rv = rsi(c, 14);
    const trades = [];
    let inPos = false;
    let entry = 0;
    let entryEquity = 1;
    let equity = 1;
    let peak = 1;
    let maxDD = 0;
    function mark(px) {
      const mtm = inPos ? entryEquity * (px / entry) : equity;
      peak = Math.max(peak, mtm);
      maxDD = Math.min(maxDD, mtm / peak - 1);
    }
    for (let i = 60; i < bars.length; i++) {
      let enter = false;
      let exit = false;
      if (kind === "cross") {
        enter = s5[i - 1] != null && s20[i - 1] != null && s5[i] != null && s20[i] != null && s5[i - 1] <= s20[i - 1] && s5[i] > s20[i];
        exit = s5[i - 1] != null && s20[i - 1] != null && s5[i] != null && s20[i] != null && s5[i - 1] >= s20[i - 1] && s5[i] < s20[i];
      } else if (kind === "rsi") {
        enter = rv[i - 1] != null && rv[i] != null && rv[i - 1] < 30 && rv[i] >= 30;
        exit = rv[i] != null && rv[i] > 70;
      } else {
        let hh = -Infinity;
        let ll = Infinity;
        for (let j = i - 20; j < i; j++) hh = Math.max(hh, bars[j].h);
        for (let j = i - 10; j < i; j++) ll = Math.min(ll, bars[j].l);
        enter = c[i] > hh && s60[i] != null && c[i] > s60[i];
        exit = c[i] < ll;
      }
      if (inPos && exit) {
        const ret = c[i] / entry - 1;
        trades.push(ret);
        equity = entryEquity * (1 + ret);
        inPos = false;
        mark(c[i]);
      } else if (!inPos && enter) {
        inPos = true;
        entry = c[i];
        entryEquity = equity;
        mark(c[i]);
      } else mark(c[i]);
    }
    const wins = trades.filter(function (r) { return r > 0; });
    const losses = trades.filter(function (r) { return r <= 0; });
    const grossWin = wins.reduce(function (s, r) { return s + r; }, 0);
    const grossLoss = losses.reduce(function (s, r) { return s + r; }, 0);
    const avg = trades.length ? trades.reduce(function (s, r) { return s + r; }, 0) / trades.length : 0;
    return {
      trades: trades.length,
      open: inPos,
      winRate: trades.length ? wins.length / trades.length : null,
      profitFactor: grossLoss < 0 ? grossWin / Math.abs(grossLoss) : (grossWin > 0 ? null : 0),
      maxDD: maxDD,
      avg: avg,
      equity: equity
    };
  }

  async function backtest(opts) {
    opts = opts || {};
    const lmt = opts.range === "5y" ? 1300 : opts.range === "3y" ? 780 : 260;
    const daily = await kline(opts.secid, 101, lmt);
    const kind = opts.strategy || "cross";
    const m = tradeMetrics(daily, kind);
    const names = { cross: "5 日與 20 日均線交叉", rsi: "RSI 跌破 30 回升、70 出場", breakout: "突破 20 日高、跌破 10 日低出場" };
    const tips = [];
    if (m.trades < 8) tips.push("完成的交易不到 8 筆，勝率還不穩。拉長到三年或五年，或改看突破策略。");
    if (m.profitFactor != null && m.profitFactor < 1) tips.push("獲利因子小於 1。只在收盤站上 60 日均線時允許進場，並把停損收在 1.5 倍 ATR。");
    if (m.winRate != null && m.winRate >= 0.6 && m.profitFactor != null && m.profitFactor < 1.3) tips.push("勝率不低，但賺的單太小。停利至少放到 2 倍停損，不要一有利潤就平倉。");
    if (m.maxDD < -0.25) tips.push("最大回撤超過 25%。同樣信號把部位減半，或加一條「週線在 20 週均線下不做多」。");
    if (m.winRate != null && m.winRate < 0.4 && m.trades >= 8) tips.push("勝率低於四成。進場改成只做突破，並要求量能高於 20 日均量。");
    if (!tips.length) tips.push("這組數字還站得住。下一步用另一個市場的同類股票再跑一次，確認不是單一標的的巧合。");
    return {
      name: daily.symbolName || opts.secid,
      strategy: names[kind] || kind,
      rangeLabel: opts.range === "5y" ? "五年" : opts.range === "3y" ? "三年" : "一年",
      bars: daily.length,
      metrics: m,
      tips: tips
    };
  }

  function returnsMap(bars) {
    const map = new Map();
    for (let i = 1; i < bars.length; i++) {
      const prev = bars[i - 1].c;
      if (prev) map.set(bars[i].t.slice(0, 10), bars[i].c / prev - 1);
    }
    return map;
  }

  function aligned(a, b) {
    const xs = [];
    const ys = [];
    a.forEach(function (v, day) {
      if (b.has(day)) {
        xs.push(v);
        ys.push(b.get(day));
      }
    });
    return { xs: xs, ys: ys };
  }

  function betaOf(xs, ys) {
    const n = xs.length;
    if (n < 30) return null;
    let mx = 0, my = 0;
    for (let i = 0; i < n; i++) { mx += xs[i]; my += ys[i]; }
    mx /= n; my /= n;
    let num = 0, den = 0;
    for (let i = 0; i < n; i++) {
      num += (xs[i] - mx) * (ys[i] - my);
      den += (ys[i] - my) * (ys[i] - my);
    }
    if (!den) return null;
    return num / den;
  }

  function pearson(xs, ys) {
    const n = xs.length;
    if (n < 30) return null;
    let mx = 0, my = 0;
    for (let i = 0; i < n; i++) { mx += xs[i]; my += ys[i]; }
    mx /= n; my /= n;
    let num = 0, dx = 0, dy = 0;
    for (let i = 0; i < n; i++) {
      const a = xs[i] - mx;
      const b = ys[i] - my;
      num += a * b; dx += a * a; dy += b * b;
    }
    if (!dx || !dy) return null;
    return num / Math.sqrt(dx * dy);
  }

  async function historyBars(secid, code, days) {
    const want = Math.max(40, Number(days) || 180);
    const stockId = twStockId(secid, code);
    if (stockId) {
      const rows = await finMind("TaiwanStockPrice", stockId, isoDaysAgo(Math.ceil(want * 1.7) + 40)).catch(function () { return []; });
      const bars = rows.map(function (row) {
        return {
          t: row.date,
          o: num(row.open),
          c: num(row.close),
          h: num(row.max),
          l: num(row.min),
          v: num(row.Trading_Volume) || 0
        };
      }).filter(function (b) { return b.c != null && b.c > 0; });
      if (bars.length >= 20) {
        const cut = bars.slice(-want);
        cut.symbolName = toTW(code || stockId);
        return cut;
      }
    }
    if (String(secid || "").indexOf("tw.") === 0) {
      throw new Error("沒有這段行情");
    }
    const series = await kline(secid, 101, want);
    if (!series.length) throw new Error("沒有這段行情");
    if (series.symbolName) series.symbolName = toTW(series.symbolName);
    return series;
  }

  async function riskReport(opts) {
    opts = opts || {};
    const holdings = (opts.holdings || []).filter(function (h) { return h.secid && Number(h.shares) > 0; });
    if (holdings.length < 1) throw new Error("先加入至少一檔持股");
    const cap = { "保守": 0.15, "穩健": 0.25, "積極": 0.4 }[opts.profile] || 0.25;
    const loadedAll = await mapPool(holdings, 3, async function (h) {
      try {
        const series = await historyBars(h.secid, h.code, 180);
        return {
          holding: h,
          bars: series,
          name: toTW(h.name || series.symbolName || h.code),
          ok: true
        };
      } catch (err) {
        return {
          holding: h,
          bars: null,
          name: toTW(h.name || h.code),
          ok: false,
          reason: err && err.message ? err.message : "沒有行情"
        };
      }
    });
    const failed = loadedAll.filter(function (row) { return !row.ok; });
    const loaded = loadedAll.filter(function (row) { return row.ok; });
    if (!loaded.length) throw new Error("持股都讀不到行情，請稍後再試");
    const market = await kline("100.SPX", 101, 180);
    const mkt = returnsMap(market);
    const priced = loaded.map(function (row) {
      const qBars = row.bars;
      const last = qBars[qBars.length - 1].c;
      const shares = Number(row.holding.shares);
      const value = last * shares;
      const cost = Number(row.holding.cost);
      const pack = aligned(returnsMap(qBars), mkt);
      return {
        secid: row.holding.secid,
        code: row.holding.code,
        name: row.name,
        shares: shares,
        cost: isFinite(cost) ? cost : null,
        price: last,
        value: value,
        pnl: isFinite(cost) ? (last - cost) * shares : null,
        beta: betaOf(pack.xs, pack.ys),
        rets: returnsMap(qBars)
      };
    });
    const total = priced.reduce(function (s, row) { return s + row.value; }, 0);
    priced.forEach(function (row) { row.weight = total ? row.value / total : 0; });
    const portBeta = priced.reduce(function (s, row) { return s + row.weight * (row.beta || 1); }, 0);
    const pairs = [];
    for (let a = 0; a < priced.length; a++) {
      for (let b = a + 1; b < priced.length; b++) {
        const pack = aligned(priced[a].rets, priced[b].rets);
        const rho = pearson(pack.xs, pack.ys);
        if (rho != null && rho >= 0.75) {
          pairs.push({ a: priced[a].code, b: priced[b].code, rho: rho });
        }
      }
    }
    const heavy = priced.filter(function (row) { return row.weight > cap; });
    const weak = [];
    if (failed.length) {
      weak.push("以下持股暫時讀不到足夠行情，這次先略過：" + failed.map(function (row) {
        return (row.holding.code || row.name) + (row.reason ? "（" + row.reason + "）" : "");
      }).join("、") + "。");
    }
    if (heavy.length) weak.push("單一帶超過「" + (opts.profile || "穩健") + "」上限 " + Math.round(cap * 100) + "%：" + heavy.map(function (row) { return row.code; }).join("、") + "。");
    if (pairs.length) weak.push("這些組合走勢幾乎綁在一起，分散效果有限：" + pairs.map(function (p) { return p.a + "/" + p.b; }).join("、") + "。");
    const oneMarket = {};
    holdings.forEach(function (h) { oneMarket[toTW(h.market || "未標")] = (oneMarket[toTW(h.market || "未標")] || 0) + 1; });
    const regions = Object.keys(oneMarket);
    if (regions.length === 1) weak.push("持股都在" + regions[0] + "，地區風險沒有分開。");
    if (!weak.length) weak.push("權重沒有明顯超過上限，也沒有相關係數高於 0.75 的配對。");
    const weights = priced.map(function (row) { return row.weight; });
    let room = weights.map(function (w) { return Math.min(w, cap); });
    let leftover = 1 - room.reduce(function (s, w) { return s + w; }, 0);
    const under = room.map(function (w) { return Math.max(0, cap - w); });
    const underSum = under.reduce(function (s, w) { return s + w; }, 0);
    if (leftover > 0.001 && underSum > 0) {
      room = room.map(function (w, i) { return w + leftover * (under[i] / underSum); });
      leftover = 0;
    }
    const plan = priced.map(function (row, i) {
      return { code: row.code, from: row.weight, to: room[i] };
    });
    const drop = portBeta * 0.2;
    let cashFrac = null;
    if (portBeta > 0.5) cashFrac = Math.max(0, Math.min(0.9, 1 - 0.5 / portBeta));
    return {
      profile: opts.profile || "穩健",
      cap: cap,
      total: total,
      beta: portBeta,
      drop: drop,
      cashFrac: cashFrac,
      rows: priced,
      pairs: pairs,
      weak: weak,
      plan: plan,
      cashLeft: leftover
    };
  }

  function reviewJournal(trades) {
    const rows = (trades || []).slice().sort(function (a, b) {
      return String(b.date || "").localeCompare(String(a.date || "")) || String(b.id || "").localeCompare(String(a.id || ""));
    }).slice(0, 20);
    const filled = rows.filter(function (t) { return !t.missed && isFinite(Number(t.entry)) && isFinite(Number(t.exit)); });
    const missed = rows.filter(function (t) { return t.missed || /錯過/.test(t.note || ""); });
    const pnls = filled.map(function (t) {
      const qty = Number(t.qty) > 0 ? Number(t.qty) : 1;
      const diff = String(t.side) === "放空" ? Number(t.entry) - Number(t.exit) : Number(t.exit) - Number(t.entry);
      return { trade: t, pnl: diff * qty, ret: Number(t.entry) ? diff / Number(t.entry) : 0 };
    });
    const wins = pnls.filter(function (p) { return p.pnl > 0; });
    const losses = pnls.filter(function (p) { return p.pnl <= 0; });
    const avgWin = wins.length ? wins.reduce(function (s, p) { return s + p.ret; }, 0) / wins.length : 0;
    const avgLoss = losses.length ? losses.reduce(function (s, p) { return s + p.ret; }, 0) / losses.length : 0;
    const noStop = filled.filter(function (t) { return !(Number(t.stop) > 0); }).length;
    const chase = rows.filter(function (t) { return t.emotion === "追價"; }).length;
    const fear = rows.filter(function (t) { return t.emotion === "恐懼提早出"; }).length;
    const revenge = rows.filter(function (t) { return t.emotion === "不甘心加碼"; }).length;
    const hesitate = rows.filter(function (t) { return t.emotion === "猶豫沒下"; }).length;
    const byCode = {};
    losses.forEach(function (p) {
      const code = p.trade.code || p.trade.symbol || "未命名";
      byCode[code] = (byCode[code] || 0) + 1;
    });
    let repeatCode = "";
    let repeatN = 0;
    Object.keys(byCode).forEach(function (code) {
      if (byCode[code] > repeatN) { repeatN = byCode[code]; repeatCode = code; }
    });
    const biases = [];
    if (chase >= 3 || (rows.length && chase / rows.length >= 0.3)) biases.push("追價出現 " + chase + " 次，進場常常發生在價格已經離開計畫之後。");
    if (fear >= 2) biases.push("有 " + fear + " 筆因為恐懼提早出場，獲利單容易留不住。");
    if (revenge >= 2) biases.push("不甘心加碼出現 " + revenge + " 次，虧損後擴大部位。");
    if (hesitate >= 2 || missed.length >= 3) biases.push("猶豫或明確記成錯過的有 " + (hesitate + missed.length) + " 筆，條件到了卻沒有執行。");
    if (!biases.length) biases.push(rows.length < 5 ? "最近樣本還少，行為偏誤還不明顯。" : "這 20 筆裡沒有單一情緒反覆超過門檻。");
    const rules = [];
    if (chase >= 2) rules.push("下單前先寫進場價。現價偏離那個價格超過 1%，這筆就放棄。");
    if (noStop >= Math.max(2, Math.ceil(filled.length / 2))) rules.push("沒有寫停損價之前，不送出委託。");
    if (avgLoss && avgWin && Math.abs(avgLoss) > avgWin) rules.push("停損固定用 1 倍 ATR，停利至少放到 2 倍停損，避免虧損單大於獲利單。");
    if (repeatN >= 3) rules.push(repeatCode + " 已連續虧損 " + repeatN + " 筆。這檔先休息 5 個交易日，期間不開新倉。");
    if (missed.length >= 2 || hesitate >= 2) rules.push("條件符合時先掛限價單，不把「再看看」留到收盤。每週檢討一次錯過清單。");
    if (fear >= 2) rules.push("進場當下寫好停利價。碰到停利之前，不因為盤中來回而手動平倉。");
    const fillers = [
      "每一筆先寫進場、停損、停利，三個價格齊了才下單。",
      "同一天虧損兩筆之後，當天不再開新倉。",
      "只做自選股裡週線仍在 20 週均線上的標的。"
    ];
    fillers.forEach(function (line) {
      if (rules.length < 3 && rules.indexOf(line) < 0) rules.push(line);
    });
    return {
      sample: rows.length,
      filled: filled.length,
      missed: missed.length,
      winRate: pnls.length ? wins.length / pnls.length : null,
      avgWin: avgWin,
      avgLoss: avgLoss,
      noStop: noStop,
      biases: biases,
      rules: rules.slice(0, 3),
      small: rows.length < 5
    };
  }

  function normalizeInvCode(token) {
    let s = String(token || "").toUpperCase().replace(/[^0-9A-Z]/g, "");
    if (!s) return "";
    // 常見 OCR：DOSEIA→00981A、OO985A→00985A
    s = s
      .replace(/^DOSEIA$/, "00981A")
      .replace(/^DO981A$/, "00981A")
      .replace(/^OO985A$/, "00985A")
      .replace(/^0O985A$/, "00985A")
      .replace(/^OO403A$/, "00403A");
    const letter = /[A-Z]$/.test(s) ? s.slice(-1) : "";
    let body = letter ? s.slice(0, -1) : s;
    body = body
      .replace(/O/g, "0")
      .replace(/Q/g, "0")
      .replace(/D/g, "0")
      .replace(/I/g, "1")
      .replace(/L/g, "1")
      .replace(/Z/g, "2")
      .replace(/S/g, "5")
      .replace(/B/g, "8")
      .replace(/G/g, "9")
      .replace(/A/g, "5");
    body = body.replace(/[^0-9]/g, "");
    if (letter) {
      if (body.length < 4 || body.length > 6) return "";
      return body + letter;
    }
    if (!/^\d{4}$/.test(body)) return "";
    return body;
  }

  function isTwInvCode(code) {
    if (/^\d{4,6}[A-Z]$/.test(code)) return true;
    if (!/^\d{4}$/.test(code)) return false;
    const n = Number(code);
    // 避開把損益／淨值片段誤當代號（如 1019、1384、3604）
    return n >= 1101 && n <= 9950;
  }

  function lookLikeShare(n) {
    if (!(n > 0) || n > 200000) return false;
    if (n === 100 || n === 200 || n === 500) return true;
    if (n >= 1000 && n % 1000 === 0) return true;
    if (n >= 100 && n % 100 === 0 && n <= 50000) return true;
    return false;
  }

  const INV_ALIASES = [
    { re: /00403A|統一升級/i, code: "00403A", name: "主動統一升級50" },
    { re: /00981A|統一台股增長|統一台設增長/i, code: "00981A", name: "主動統一台股增長" },
    { re: /00985A|野村台灣/i, code: "00985A", name: "主動野村台灣50" },
    { re: /2345|智邦/, code: "2345", name: "智邦" },
    { re: /2382|廣達/, code: "2382", name: "廣達" },
    { re: /3037|欣興/, code: "3037", name: "欣興" },
    { re: /2727|王品/, code: "2727", name: "王品" },
    { re: /2330|台積電/, code: "2330", name: "台積電" }
  ];

  // StockJason／富邦匯出：{ source, holdings:[{code,todayQty,tradableQty,costPrice,raw}] }
  function parseFubonHoldingsJson(raw) {
    let data = raw;
    if (typeof raw === "string") {
      try { data = JSON.parse(raw); } catch (err) { return []; }
    }
    if (!data || typeof data !== "object") return [];
    const list = Array.isArray(data.holdings) ? data.holdings
      : (Array.isArray(data) ? data : []);
    const out = [];
    const seen = {};
    list.forEach(function (row) {
      if (!row || typeof row !== "object") return;
      const code = String(row.code || row.stock_no || (row.raw && row.raw.stock_no) || "")
        .trim().toUpperCase();
      if (!code || seen[code]) return;
      const shares = Number(row.tradableQty != null ? row.tradableQty
        : (row.todayQty != null ? row.todayQty
          : (row.raw && (row.raw.tradable_qty != null ? row.raw.tradable_qty : row.raw.today_qty))));
      if (!(shares > 0)) return;
      let cost = Number(row.costPrice != null ? row.costPrice
        : (row.raw && row.raw.cost_price));
      if (!(cost > 0) && row.raw && Number(row.raw.buy_value) > 0) {
        cost = Number(row.raw.buy_value) / shares;
      }
      let pnl = null;
      if (row.raw) {
        const up = Number(row.raw.unrealized_profit);
        const down = Number(row.raw.unrealized_loss);
        if (up > 0) pnl = up;
        else if (down > 0) pnl = -down;
      }
      seen[code] = true;
      out.push({
        code: code,
        name: String(row.name || "").trim(),
        shares: shares,
        cost: cost > 0 ? cost : null,
        pnl: pnl,
        pct: null
      });
    });
    return out;
  }

  function parseInventory(raw) {
    let text = String(raw || "");
    text = text.replace(/[０-９]/g, function (ch) {
      return String.fromCharCode(ch.charCodeAt(0) - 0xFEE0);
    });
    text = text.replace(/[—–−]/g, "-");
    text = text.replace(/([\u4e00-\u9fff])\s+(?=[\u4e00-\u9fff])/g, "$1");
    text = text.replace(/[|「」“”"'【】\[\]_。]/g, " ");
    text = text.replace(/(\d),(?=\d{3}(\D|$))/g, "$1");
    // 千分位小數（淨值）不要併成假代號：36.291 → 保留
    text = text.replace(/(\d)\.(\d{3})(?!\d)/g, function (m, a, b) {
      // 僅當像「10.000」股數寫法才合併；淨值／成本維持空白隔開
      if (Number(a + b) <= 100000 && /000$/.test(b)) return a + b;
      return a + " " + b;
    });
    const noiseName = /返回|庫存|說明|帳務|損益|股票|交易|頁次|筆數|調整|成本|配息|融資|首頁|行情|桃園|反沖|重查|現買|現賣|現股|現設|現投|股數|均價|類別|名稱|餘額|試算|利率|真次|淨值|付出/;
    const aliasCodes = {};
    INV_ALIASES.forEach(function (a) { aliasCodes[a.code] = a; });

    function cleanName(source) {
      const found = String(source || "").match(/[\u4e00-\u9fff][\u4e00-\u9fff0-9A-Za-z]{1,20}/g) || [];
      for (let i = found.length - 1; i >= 0; i--) {
        const name = found[i].replace(/現股|現設|現投/g, "");
        if (name.length >= 2 && !noiseName.test(name)) return name;
      }
      return "";
    }

    function parsePctToken(sign, num) {
      let p = Number(num);
      // OCR 常丟小數點：+115%→1.15、+24%→2.4、+281%→2.81
      if (!/\./.test(num)) {
        if (p >= 100) p = p / 100;
        else if (p >= 10) p = p / 10;
      }
      if (sign === "-") p = -Math.abs(p);
      else if (sign === "+") p = Math.abs(p);
      return p;
    }

    // 成本均價＝買入價（欄尾單價；以淨值／付出成本成對校準，避免把 1500 當總額）
    function pickAvgCost(nums, shares) {
      if (!(shares > 0) || !nums || !nums.length) return null;
      const totals = nums.filter(function (n) {
        return n !== shares && n >= shares * 2 && n / shares >= 0.5 && n / shares <= 20000;
      }).sort(function (a, b) { return b - a; });
      let paid = null;
      for (let i = 0; i < totals.length - 1; i++) {
        if (totals[i + 1] / totals[i] >= 0.9) {
          paid = totals[i + 1];
          break;
        }
      }
      if (paid == null) {
        for (let i = 0; i < totals.length; i++) {
          const n = totals[i];
          if (n >= Math.max(shares * 30, 20000) || (shares >= 1000 && n >= shares * 3)) {
            paid = n;
            break;
          }
        }
      }
      let paidAvg = null;
      if (paid != null) {
        const avg = paid / shares;
        if (avg >= 0.2 && avg <= 20000) paidAvg = avg;
      }
      // 1) 欄尾單價：須接近付出成本均價（防下一列小數混入）
      for (let i = nums.length - 1; i >= 0; i--) {
        const n = nums[i];
        if (n === shares || n < 0.2 || n > 20000) continue;
        if (paid != null && n >= paid * 0.9) continue;
        if (paidAvg != null) {
          if (Math.abs(n - paidAvg) / paidAvg <= 0.08) return Math.round(n * 100) / 100;
        } else if (Math.abs(n - Math.round(n)) > 1e-9) {
          return n;
        }
      }
      // 2) 沒印出均價時用付出成本 ÷ 股數
      if (paidAvg != null) return Math.round(paidAvg * 100) / 100;
      // 3) OCR 常丟小數：886→8.86、2404→24.04、30043→300.43
      for (let i = nums.length - 1; i >= 0; i--) {
        const n = nums[i];
        if (n === shares || n !== Math.round(n)) continue;
        if (n >= 10000 && n <= 9999999) {
          const c = n / 100;
          if (c >= 0.5 && c <= 20000) return Math.round(c * 100) / 100;
        }
        if (shares >= 1000 && n >= 100 && n < 100000) {
          const c = n / 100;
          if (c >= 0.5 && c <= 500) return Math.round(c * 100) / 100;
        }
      }
      // 4) 整數單價（如 1500、750）
      for (let i = nums.length - 1; i >= 0; i--) {
        const n = nums[i];
        if (n !== shares && n >= 1 && n <= 20000 && !lookLikeShare(n)) return n;
      }
      return null;
    }

    // fromEnd：代號在後時，取最靠近代號的股數／％
    function pickSharesAndPnl(source, fromEnd) {
      const src = String(source || "");
      let pct = null;
      const pctAll = [];
      const pctRe = /([+-]?)(\d+(?:\.\d+)?)\s*%/g;
      let pm;
      while ((pm = pctRe.exec(src))) pctAll.push(parsePctToken(pm[1], pm[2]));
      if (pctAll.length) pct = fromEnd ? pctAll[pctAll.length - 1] : pctAll[0];

      const cleaned = src.replace(/[+-]?\d+(?:\.\d+)?\s*%/g, " ");
      const tokens = cleaned.match(/[+-]?\d+(?:\.\d+)?/g) || [];
      const signed = [];
      const nums = [];
      tokens.forEach(function (token) {
        const value = Number(token.replace(/,/g, ""));
        if (!isFinite(value) || value === 0) return;
        if (token.charAt(0) === "-" || token.charAt(0) === "+") {
          if (Math.abs(value) < 100 && token.indexOf(".") >= 0) return;
          signed.push(value);
          return;
        }
        nums.push(value);
      });
      const shareCands = nums.filter(function (n) {
        return lookLikeShare(n) && n <= 100000;
      });
      const shares = shareCands.length
        ? (fromEnd ? shareCands[shareCands.length - 1] : shareCands[0])
        : null;
      if (!(shares > 0)) {
        return { shares: null, pnl: signed.length ? (fromEnd ? signed[signed.length - 1] : signed[0]) : null, cost: null, pct: pct };
      }
      let pnl = signed.length ? (fromEnd ? signed[signed.length - 1] : signed[0]) : null;
      if (pct != null) {
        const near = nums.filter(function (n) {
          return n !== shares && n < Math.max(shares * 20, 50000) && n >= 1;
        });
        if (pnl == null && near.length) {
          pnl = fromEnd ? near[near.length - 1] : (near.find(function (n) { return n < 100000; }) || near[0]);
        }
        if (pnl != null && pct < 0 && pnl > 0) pnl = -pnl;
        if (pnl != null && pct > 0 && pnl < 0) pnl = Math.abs(pnl);
      }
      // 沒有獲利率時，過小損益多半是 OCR 碎片（如 30、3）
      if (pnl != null && pct == null && Math.abs(pnl) < 20) pnl = null;
      const cost = pickAvgCost(nums, shares);
      return { shares: shares, pnl: pnl, cost: cost, pct: pct };
    }

    function parseBlock(block) {
      const lines = String(block || "").split(/\n/).map(function (line) {
        return line.replace(/\s+/g, " ").trim();
      }).filter(function (line) {
        return line && !/帳號|總損益|頁次|返回|重查|成本扣息|調整帳務|其他庫存|帳務模式|先進先出|首頁|自選報價|交易帳務|市場行情|新增自選|損益試算方式|---PSM/.test(line);
      });
      const joined = lines.join("\n");
      const found = {};

      function put(code, name, money, score) {
        if (!code || !(money && money.shares > 0)) return;
        const prev = found[code];
        if (!prev || score > prev.score) {
          found[code] = {
            code: code,
            name: name || "",
            shares: money.shares,
            pnl: money.pnl,
            cost: money.cost,
            pct: money.pct,
            score: score
          };
        }
      }

      // 含 OCR 變形：DOSEIA、OO985A、00ogaA
      const codeRe = /(?<![0-9A-Za-z])((?:(?:00|DO|OO|0O)[0-9OQIlSGBZodgaD]{3,5}[A-Za-z])|(?:[0-9]{4}))(?![0-9A-Za-z])/gi;
      let match;
      while ((match = codeRe.exec(joined))) {
        const rawCode = match[1];
        const prev2 = joined.slice(Math.max(0, match.index - 2), match.index);
        if (/[+]/.test(prev2)) continue;
        if (joined.charAt(match.index - 1) === "-") continue;
        const code = normalizeInvCode(rawCode);
        if (!isTwInvCode(code)) continue;
        if (/^(?:100|200|500|1000|2000|3000|5000|10000)$/.test(code)) continue;
        // 元大列：股數…淨值、付出成本、成本均價約 50～70 字；均價用付出成本校準防吃下一檔
        const afterNear = joined.slice(match.index + rawCode.length, match.index + rawCode.length + 72);
        const afterFar = joined.slice(match.index + rawCode.length, match.index + rawCode.length + 100);
        const head = joined.slice(Math.max(0, match.index - 24), match.index);
        const before = joined.slice(Math.max(0, match.index - 100), match.index);
        const known = aliasCodes[code];
        // 代號後短距沒數字 → 視為列尾代號，優先往前取，避免吃到下一檔
        const afterHasNum = /\d/.test(joined.slice(match.index + rawCode.length, match.index + rawCode.length + 12));
        let money = { shares: null, pnl: null, cost: null, pct: null };
        let fromBefore = false;
        if (afterHasNum) money = pickSharesAndPnl(afterNear, false);
        if (!(money.shares > 0) && (known || /現[股設投]/.test(before) || /[A-Z]$/.test(code))) {
          money = pickSharesAndPnl(before, true);
          fromBefore = !!(money.shares > 0);
        }
        if (!(money.shares > 0) && afterHasNum) money = pickSharesAndPnl(afterFar, false);
        if (!(money.shares > 0)) money = pickSharesAndPnl(afterFar, false);
        if (!(money.shares > 0)) continue;
        const isEtf = /[A-Z]$/.test(code);
        const marked = /現[股設投買]|主動/.test(head + before.slice(-30) + afterNear.slice(0, 20));
        // 純四碼：必須是已知持股，或緊鄰「現股／現設」標記
        if (!isEtf && !known && !marked) continue;
        if (!isEtf && !known && money.shares > 20000) continue;
        let score = isEtf ? 6 : 4;
        if (known) score += 3;
        if (marked) score += 2;
        if (money.pct != null) score += 1;
        if (!fromBefore) score += 1;
        put(code, known ? known.name : cleanName(head + before), money, score);
      }

      INV_ALIASES.forEach(function (alias) {
        if (found[alias.code]) return;
        const m = alias.re.exec(joined);
        if (!m) return;
        const after = joined.slice(m.index + m[0].length, m.index + m[0].length + 100);
        const before = joined.slice(Math.max(0, m.index - 100), m.index);
        let money = pickSharesAndPnl(after, false);
        if (!(money.shares > 0)) money = pickSharesAndPnl(before, true);
        if (!(money.shares > 0)) return;
        put(alias.code, alias.name, money, 3);
      });

      return Object.keys(found).map(function (k) { return found[k]; });
    }

    // 多 PSM 分開解析再投票，避免串行
    const blocks = text.split(/---PSM\d*---/i).filter(function (b) { return b.trim(); });
    const vote = {};
    (blocks.length ? blocks : [text]).forEach(function (block) {
      parseBlock(block).forEach(function (row) {
        if (!vote[row.code]) vote[row.code] = [];
        vote[row.code].push(row);
      });
    });

    const rows = [];
    Object.keys(vote).forEach(function (code) {
      const list = vote[code];
      const shareCount = {};
      list.forEach(function (r) {
        shareCount[r.shares] = (shareCount[r.shares] || 0) + 1 + (r.score || 0) * 0.01;
      });
      let bestShares = list[0].shares;
      let bestN = -1;
      Object.keys(shareCount).forEach(function (s) {
        if (shareCount[s] > bestN) {
          bestN = shareCount[s];
          bestShares = Number(s);
        }
      });
      const pick = list.filter(function (r) { return r.shares === bestShares; })
        .sort(function (a, b) {
          const ca = a.cost > 0 ? 2 : 0;
          const cb = b.cost > 0 ? 2 : 0;
          return (cb + (b.score || 0)) - (ca + (a.score || 0));
        })[0] || list[0];
      // 非別名的四碼：至少要被兩個區塊看到，或分數夠高
      const known = aliasCodes[code];
      if (!known && !/[A-Z]$/.test(code) && list.length < 2 && (pick.score || 0) < 6) return;
      let cost = pick.cost;
      if (!(cost > 0)) {
        const withCost = list.find(function (r) { return r.shares === bestShares && r.cost > 0; });
        if (withCost) cost = withCost.cost;
      }
      rows.push({
        code: code,
        name: pick.name || (known ? known.name : ""),
        shares: bestShares,
        pnl: pick.pnl,
        cost: cost,
        pct: pick.pct
      });
    });

    // 若別名持股已齊，丟掉無名雜訊代號
    const aliasHits = rows.filter(function (r) { return aliasCodes[r.code]; }).length;
    if (aliasHits >= 3) {
      return rows.filter(function (r) {
        return aliasCodes[r.code] || /[A-Z]$/.test(r.code);
      });
    }
    return rows;
  }

  function twStockId(secid, code) {
    const id = String(secid || "");
    const c = String(code || "").toUpperCase();
    if (id.indexOf("178.") === 0 || id.indexOf("tw.") === 0) return c || id.slice(id.indexOf(".") + 1);
    if (/^\d{4,6}[A-Z]?$/.test(c)) return c;
    return "";
  }

  async function finMind(dataset, stockId, start) {
    const url = "https://api.finmindtrade.com/api/v4/data?dataset=" + encodeURIComponent(dataset) +
      "&data_id=" + encodeURIComponent(stockId) + "&start_date=" + encodeURIComponent(start);
    const res = await fetch(url);
    if (!res.ok) throw new Error(dataset + " 讀取失敗");
    const json = await res.json();
    return Array.isArray(json.data) ? json.data : [];
  }

  function chipTone(net, vol) {
    const r = vol > 0 ? net / vol : 0;
    if (r >= 0.08) return { label: "大買", cls: "up" };
    if (r >= 0.02) return { label: "中買", cls: "up" };
    if (r > -0.02) return { label: "中立", cls: "" };
    if (r > -0.08) return { label: "中賣", cls: "down" };
    return { label: "大賣", cls: "down" };
  }

  function rateTrend(now, prev) {
    if (now == null || prev == null || !isFinite(now) || !isFinite(prev)) return { text: "—", cls: "" };
    const d = now - prev;
    if (Math.abs(d) < 0.05) return { text: "持平", cls: "" };
    return d > 0 ? { text: "上升", cls: "up" } : { text: "下降", cls: "down" };
  }

  function yearEps(rows) {
    const byYear = {};
    rows.forEach(function (row) {
      if (row.type !== "EPS" || row.value == null) return;
      const y = String(row.date).slice(0, 4);
      if (!byYear[y]) byYear[y] = { year: y, sum: 0, n: 0, dates: [] };
      byYear[y].sum += Number(row.value);
      byYear[y].n += 1;
      byYear[y].dates.push(row.date);
    });
    return Object.keys(byYear).sort().map(function (y) { return byYear[y]; });
  }

  function quarterBag(rows) {
    const byDate = {};
    rows.forEach(function (row) {
      if (!byDate[row.date]) byDate[row.date] = { date: row.date };
      byDate[row.date][row.type] = num(row.value);
    });
    return Object.keys(byDate).sort().map(function (d) { return byDate[d]; });
  }

  function tickSize(price) {
    const p = Math.abs(price);
    if (p < 10) return 0.01;
    if (p < 50) return 0.05;
    if (p < 100) return 0.1;
    if (p < 500) return 0.5;
    if (p < 1000) return 1;
    return 5;
  }

  function ceilTick(price) {
    const t = tickSize(price);
    return Math.round(Math.ceil(price / t - 1e-9) * t * 10000) / 10000;
  }

  function floorTick(price) {
    const t = tickSize(price);
    return Math.round(Math.floor(price / t + 1e-9) * t * 10000) / 10000;
  }

  function formatLevelPx(price) {
    if (!(price > 0)) return "—";
    const t = tickSize(price);
    if (t >= 1) return Math.round(price).toLocaleString("zh-Hant");
    if (t >= 0.1) return price.toFixed(1);
    return price.toFixed(2);
  }

  function avgRange(bars, n) {
    const take = bars.slice(-Math.min(n, bars.length));
    if (!take.length) return 0;
    let sum = 0;
    take.forEach(function (b) { sum += Math.max((b.h || 0) - (b.l || 0), 0); });
    const avg = sum / take.length;
    return avg > 0 ? avg : tickSize(bars[bars.length - 1].c);
  }

  function pushAbove(list, close, level, why) {
    if (!(level > close)) return;
    list.push({ level: level, why: why });
  }

  function pushBelow(list, close, level, why) {
    if (!(level < close)) return;
    list.push({ level: level, why: why });
  }

  function pickNearest(cands, close, minGap, aboveClose) {
    if (!cands.length) return null;
    const far = aboveClose
      ? cands.filter(function (c) { return c.level >= close + minGap; })
      : cands.filter(function (c) { return c.level <= close - minGap; });
    const pool = far.length ? far : cands;
    return pool.reduce(function (best, cur) {
      if (!best) return cur;
      return aboveClose
        ? (cur.level < best.level ? cur : best)
        : (cur.level > best.level ? cur : best);
    }, null);
  }

  /** 與桌面版 TrendAnalyzer.FindLevels 對齊的簡化版（不含成交量輪廓）。 */
  function findLevels(bars) {
    if (!bars || bars.length < 5) return { breakout: null, support: null };
    const close = bars[bars.length - 1].c;
    const atr14 = avgRange(bars, 14);
    const minGap = Math.max(atr14 * 0.15, tickSize(close));
    const n20 = Math.min(20, bars.length);
    const n60 = Math.min(60, bars.length);
    const last20 = bars.slice(-n20);
    const last60 = bars.slice(-n60);
    let hi20 = -Infinity;
    let lo20 = Infinity;
    let hi60 = -Infinity;
    let lo60 = Infinity;
    last20.forEach(function (b) {
      hi20 = Math.max(hi20, b.h);
      lo20 = Math.min(lo20, b.l);
    });
    last60.forEach(function (b) {
      hi60 = Math.max(hi60, b.h);
      lo60 = Math.min(lo60, b.l);
    });
    const closes = closesOf(bars);
    const ma20 = sma(closes, 20);
    const ma60 = sma(closes, 60);
    const m20 = ma20[ma20.length - 1];
    const m60 = ma60[ma60.length - 1];
    const rangeLike = m20 != null && m60 != null && Math.abs(m20 - m60) / close < 0.02;
    const boxHi = rangeLike ? hi20 : hi60;
    const boxLo = rangeLike ? lo20 : lo60;
    const above = [];
    const below = [];
    pushAbove(above, close, boxHi, rangeLike ? "箱型上緣" : "近" + n60 + "日高");
    if (Math.abs(hi20 - boxHi) > minGap) pushAbove(above, close, hi20, "近" + n20 + "日高");
    if (m20 != null) pushAbove(above, close, m20, "MA20");
    if (m60 != null) pushAbove(above, close, m60, "MA60");
    pushBelow(below, close, boxLo, rangeLike ? "箱型下緣" : "近" + n60 + "日低");
    if (Math.abs(lo20 - boxLo) > minGap) pushBelow(below, close, lo20, "近" + n20 + "日低");
    if (m20 != null) pushBelow(below, close, m20, "MA20");
    if (m60 != null) pushBelow(below, close, m60, "MA60");

    let brkCand = pickNearest(above, close, minGap, true);
    let supCand = pickNearest(below, close, minGap, false);
    if (rangeLike) {
      const exactHi = above.find(function (c) { return Math.abs(c.level - boxHi) < 1e-6; });
      if (exactHi) brkCand = exactHi;
      if (close - boxLo <= Math.max(atr14 * 2.5, close * 0.08)) {
        const exactLo = below.find(function (c) { return Math.abs(c.level - boxLo) < 1e-6; });
        if (exactLo) supCand = exactLo;
      }
    }

    let breakout;
    if (brkCand) {
      let focus = ceilTick(brkCand.level + minGap);
      if (focus <= close) focus = ceilTick(close + tickSize(close));
      breakout = { focus: focus, text: formatLevelPx(focus), why: brkCand.why };
    } else {
      let focus = ceilTick(Math.max(hi20, close) + minGap);
      if (focus <= close) focus = ceilTick(close + tickSize(close));
      breakout = { focus: focus, text: formatLevelPx(focus), why: "站上近高" };
    }

    let support;
    if (supCand) {
      const half = Math.max(atr14 * 0.25, tickSize(supCand.level) * 2);
      let low = floorTick(supCand.level - half);
      let high = floorTick(Math.min(supCand.level + half, close - tickSize(close)));
      if (high < low) high = low;
      if (high >= close) {
        high = floorTick(close - tickSize(close));
        if (high < low) high = low;
      }
      const focus = Math.min(Math.max(floorTick(supCand.level), low), high);
      support = {
        low: low,
        high: high,
        focus: focus,
        text: low === high ? formatLevelPx(low) : formatLevelPx(low) + "–" + formatLevelPx(high),
        why: supCand.why
      };
    } else {
      const half = Math.max(atr14 * 0.25, tickSize(lo20) * 2);
      let low = floorTick(lo20 - minGap);
      let high = floorTick(Math.min(lo20 + half, close - tickSize(close)));
      if (high < low) high = low;
      support = {
        low: low,
        high: high,
        focus: floorTick(lo20),
        text: low === high ? formatLevelPx(low) : formatLevelPx(low) + "–" + formatLevelPx(high),
        why: "近低支撐"
      };
    }
    return { breakout: breakout, support: support };
  }

  let targetsCache = null;
  let targetsCachePromise = null;

  async function loadTargetsCache() {
    if (targetsCache) return targetsCache;
    if (!targetsCachePromise) {
      targetsCachePromise = fetch("targets-cache.json")
        .then(function (res) { return res.ok ? res.json() : { items: {} }; })
        .then(function (json) {
          targetsCache = json && json.items ? json : { items: {} };
          return targetsCache;
        })
        .catch(function () {
          targetsCache = { items: {} };
          return targetsCache;
        });
    }
    return targetsCachePromise;
  }

  function parseFactsetTargets(html) {
    if (!html) return null;
    const m = String(html).match(/"targetValuation":\{[^}]+\}/);
    if (!m) return null;
    try {
      const tv = JSON.parse(m[0].slice('"targetValuation":'.length));
      const high = num(tv.feHigh);
      const mean = num(tv.feMean);
      const low = num(tv.feLow);
      if (!(high > 0) && !(mean > 0) && !(low > 0)) return null;
      return {
        high: high,
        mean: mean,
        low: low,
        median: num(tv.feMedian),
        asOf: tv.rateDate || "",
        source: "cnyes"
      };
    } catch (err) {
      return null;
    }
  }

  async function fetchCnyesTargetsLive(code) {
    const target = "https://www.cnyes.com/twstock/" + encodeURIComponent(code);
    const urls = [
      "https://api.allorigins.win/raw?url=" + encodeURIComponent(target),
      "https://api.codetabs.com/v1/proxy?quest=" + encodeURIComponent(target),
      "https://corsproxy.io/?" + encodeURIComponent(target)
    ];
    for (let i = 0; i < urls.length; i++) {
      try {
        const ctrl = typeof AbortController !== "undefined" ? new AbortController() : null;
        const timer = ctrl ? setTimeout(function () { ctrl.abort(); }, 9000) : 0;
        const res = await fetch(urls[i], ctrl ? { signal: ctrl.signal } : undefined);
        if (timer) clearTimeout(timer);
        if (!res.ok) continue;
        const text = await res.text();
        const hit = parseFactsetTargets(text);
        if (hit) return hit;
      } catch (err) { /* 下一個代理 */ }
    }
    return null;
  }

  async function foreignTargets(code) {
    const id = String(code || "").toUpperCase();
    if (!id) return null;
    const cache = await loadTargetsCache();
    const hit = cache.items && cache.items[id];
    if (hit && (hit.high > 0 || hit.mean > 0 || hit.low > 0)) {
      return {
        high: num(hit.high),
        mean: num(hit.mean),
        low: num(hit.low),
        median: num(hit.median),
        asOf: hit.asOf || "",
        source: "cache"
      };
    }
    const live = await fetchCnyesTargetsLive(id);
    if (live) {
      if (!cache.items) cache.items = {};
      cache.items[id] = live;
    }
    return live;
  }

